return ['domain'=>'translate-with-ai-for-polylang','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nb_NO','project-id-version'=>'Translate with AI for Polylang 1.2.0','pot-creation-date'=>'2026-11-24T23:32:47+00:00','po-revision-date'=>'2026-11-25 00:25+0100','x-generator'=>'WP-CLI 2.12.0','messages'=>['Translate with AI for Polylang'=>'Oversett med KI for Polylang','Makes Polylang\'s "Add a translation" (+) create a linked draft that is translated with the WordPress AI Client in the background.'=>'Lar Polylangs «Legg til en oversettelse» (+) opprette et tilknyttet utkast som oversettes med WordPress AI Client i bakgrunnen.','Per Soderlind'=>'Per Soderlind','https://soderlind.no'=>'https://soderlind.no','Post not found.'=>'Fant ikke innlegget.','You are not allowed to translate this post.'=>'Du har ikke tillatelse til å oversette dette innlegget.','This post already has a translation in that language.'=>'Dette innlegget har allerede en oversettelse til det språket.','Resume bulk translation'=>'Fortsett masseoversettelsen','Retry translation'=>'Prøv oversettelsen på nytt','Bulk translation paused'=>'Masseoversettelse satt på pause','Waiting to translate to %s…'=>'Venter på å oversette til %s …','Translating to %s…'=>'Oversetter til %s …','AI translation complete'=>'KI-oversettelsen er fullført','Translation failed — view error'=>'Oversettelsen mislyktes – vis feil','This translation cannot be retried.'=>'Denne oversettelsen kan ikke prøves på nytt.','Translation to %s is queued.'=>'Oversettelse til %s er lagt i kø.','Waiting to translate to %s in the bulk queue.'=>'Venter på tur i køen for å oversette til %s.','The bulk translation queue is paused.'=>'Køen for masseoversettelse er satt på pause.','Translating to %s in the background.'=>'Oversetter til %s i bakgrunnen.','This notice will update automatically.'=>'Dette varselet oppdateres automatisk.','Avoid editing or publishing this draft until translation finishes. Edits made while the AI is working will